function openConnect(){ $('#connectModal').classList.add('open');$('#connectStatus').textContent='';$('#baseUrl').value=config.base;$('#modelInput').value=config.model;$('#apiKey').value=config.key;$('#visionToggle').classList.toggle('on',config.vision)}function saveConfig(){config.base=$('#baseUrl').value.trim();config.model=$('#modelInput').value.trim();config.key=$('#apiKey').value;config.vision=$('#visionToggle').classList.contains('on');if($('#rememberKey').checked){localStorage.setItem('rw-config',JSON.stringify(config))}$('#modelPill').textContent=config.model||'Connected';$('#connectModal').classList.remove('open');$('#connectBtn').textContent='Connected';}
